import csv
import re

data = """"Baron Sarayı (Baron Empain Palace)","Kahire","Mısır","1990'larda karanlık okült ritüellere ev sahipliği yapmış bu devasa Hint mimarisi saray. Kız kardeşi ve karısının gizemli ölümlerinin ardından Baron'un delirdiği bu yapıda, geceleri duyulan ayin sesleri, kendiliğinden döndüğüne inanılan ana kule ve kan donduran ifrit (cin) enerjisi auranızı felç eder.",5"Roushdy Binası (Cinli Apartman)","İskenderiye","Mısır","Mısır'ın en ünlü şehir efsanelerinden biri olan ve boyut dışı varlıkların (ifritlerin) sahiplendiği bu devasa terk edilmiş bina. Duvarlarından kan sızdığı, içeri girmeye çalışanların eşyalarının şiddetle fırlatıldığı bu yapı, doğrudan alt boyut varlıklarının aktif bir yuvasıdır; önünden geçerken bile o agresif karanlığı hissedersiniz.",5"Krallar Vadisi (Firavun'un Laneti)","Luksor","Mısır","Tutankhamun'un mezarının da bulunduğu bu devasa ölüm vadisi, binlerce yıllık kara büyülerle ve kadim koruma mühürleriyle korunmaktadır. Güneş battıktan sonra vadinin o boğucu ve sıcak rüzgarına karışan antik fısıltılar ve mezar hırsızlarına edilen lanetlerin yarattığı ağır ölüm frekansı zihninizi ezer.",5"Osiris Şaftı (Yeraltı Labirenti)","Giza","Mısır","Giza Platosu'nun altına doğru uzanan, sularla kaplı ve katmanlı bu gizli yeraltı mezarı. Mitolojik yeraltı tanrısı Osiris'e adanan bu zifiri karanlık kuyuya inildiğinde, yerkürenin o yoğun, hipnotik ve karanlık enerjisiyle karşılaşırsınız; buradaki astral ağırlık, insan iradesini sıfırlayan güçlü bir alt boyut kapısıdır.",5"Karnak Tapınağı (Sekhmet'in Sığınağı)","Luksor","Mısır","Savaş, yıkım ve salgın hastalık tanrıçası Sekhmet'in heykeline ev sahipliği yapan loş ve karanlık oda. Binlerce yıllık kanlı adakların titreşimini taşıyan bu heykelin karşısında durduğunuzda, devasa ve ilkel bir dişil öfke auranızı delip geçer; birçok ziyaretçi burada istemsizce transa veya panik atağa girer.",4"Dashur Kızıl Piramit Dehlizleri","Giza","Mısır","Giza'nın turistik piramitlerinden uzakta, çok daha klostrofobik ve ağır enerjili olan bu yapının zifiri dehlizleri. İçerideki havanın ağır amonyak kokusu ve binlerce tonluk taşların yarattığı o ezici baskı yeraltı tanrılarının frekansını hissettirir; tünellerde ilerlerken oksijenin ve zaman algısının tamamen kaybolduğunu fark edersiniz.",4"El Bagawat Nekropolü","Harga Vahası","Mısır","Çölün acımasız ıssızlığında, binlerce eski Hristiyan mumyasının bulunduğu devasa kerpiç mezarlık. Geceleri çöl rüzgarı bu yüzlerce kubbeli mezarın arasından geçerken, dünyadan tamamen izole olmuş ölülerin feryatlarını taşır. Buradaki kimsesizlik ve unutulmuşluk enerjisi, kalbinize doğrudan fiziksel bir acı saplar.",4"Eski Helwan Sanatoryumu","Kahire","Mısır","Kahire'nin dışında, çölün yuttuğu ve binlerce hastanın veremden acı içinde can verdiği terk edilmiş devasa şifa merkezi. Yıkık koridorlarda yankılanan bedensiz öksürükler ve rüzgarla savrulan kumların yarattığı o sarı, hastalıklı frekans, buraya girenlerin yaşam enerjisini yavaş yavaş emer.",4"Beyaz Çöl (Sahra el-Beyda)","Farafra","Mısır","Geceleri ay ışığı altında devasa, donmuş hayaletleri andıran kireçtaşı kayalıklarıyla dolu bu doğa harikası. Bedevilerin kadim hikayelerine göre çöl cinlerinin (Gûl ve İfrit) av sahası olan bu bölgede, karanlığın içinden fısıldayan seslerin kampçıları çölün derinliklerine, sonsuz bir kayboluşa çektiği anlatılır.",5"Old Cataract Hotel (Terk Edilmiş Odalar)","Asvan","Mısır","Nil nehrine bakan bu tarihi ve ihtişamlı otelin özellikle kullanılmayan eski kanatlarında 19. yüzyılın aristokratik ölüm enerjisi yatar. Gece karanlığında boş koridorlarda ayak seslerinin yankılandığı, aynalarda eski Mısır büyülerinin kurbanı olmuş gölgelerin belirdiği ve havayı aniden donduran o yoğun kederin zihni sardığı rapor edilir.",3"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

import io
reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Mısır kayitlari eklendi.")
